$function$

CREATE OR REPLACE FUNCTION public.dv_rut(cuerpo bigint)
 RETURNS character
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
declare
  n bigint := cuerpo;
  suma integer := 0;
  mult integer := 2;
  resto integer;
begin
  if n <= 0 then
    return null;
  end if;
  while n > 0 loop
    suma := suma + (n % 10) * mult;
    n := n / 10;
    mult := case when mult = 7 then 2 else mult + 1 end;
  end loop;
  resto := 11 - (suma % 11);
  return case resto
           when 11 then '0'
           when 10 then 'K'
           else resto::text
         end;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_categoria_validar_arbol()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.parent_id is not null then
    if new.parent_id = new.id then
      raise exception 'Una categoría no puede ser su propio padre.';
    end if;

    -- Serializa los cambios de jerarquía antes de evaluar las relaciones.
    perform pg_catalog.pg_advisory_xact_lock(20261021, 3);
    if exists (
      select 1 from public.categoria as padre
      where padre.id = new.parent_id and padre.parent_id is not null
    ) then
      raise exception 'Solo se permiten dos niveles: el padre debe ser una categoría raíz.';
    end if;
    if exists (
      select 1 from public.categoria as hija where hija.parent_id = new.id
    ) then
      raise exception 'No se puede asignar un padre a una categoría que tiene subcategorías.';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_contar_propuestos()
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not public.es_admin('PROPUESTOS_REVISAR') then
    raise exception 'No autorizado.' using errcode = '42501';
  end if;
  return (select pg_catalog.count(*)::int from public.alimento as a where a.estado = 'PROPUESTO');
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_aprobar_propuesto(p_id bigint, p_nombre text, p_categoria_id bigint, p_unidad_base text, p_es_perecible boolean, p_vida_util_dias_ref integer)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_estado text;
begin
  if not public.es_admin('PROPUESTOS_REVISAR') then
    raise exception 'No autorizado.' using errcode = '42501';
  end if;
  select a.estado into v_estado from public.alimento as a where a.id = p_id for update;
  if not found or v_estado <> 'PROPUESTO' then
    raise exception 'El producto ya no está pendiente de revisión.';
  end if;
  if p_nombre is null or pg_catalog.char_length(pg_catalog.btrim(p_nombre)) not between 2 and 80 then
    raise exception 'El nombre debe tener entre 2 y 80 caracteres.';
  end if;
  if not exists (select 1 from public.categoria as c where c.id = p_categoria_id and c.activa) then
    raise exception 'La categoría no existe o está inactiva.';
  end if;
  if p_vida_util_dias_ref is not null and p_vida_util_dias_ref not between 1 and 3650 then
    raise exception 'La duración debe estar entre 1 y 3650 días.';
  end if;
  update public.alimento as a set
    nombre = pg_catalog.btrim(p_nombre), categoria_id = p_categoria_id,
    unidad_base = p_unidad_base, es_perecible = p_es_perecible,
    vida_util_dias_ref = p_vida_util_dias_ref,
    estado = 'APROBADO', hogar_id = null, activo = true
  where a.id = p_id;
  return p_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_rechazar_propuesto(p_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
