$function$

CREATE OR REPLACE FUNCTION public.generar_invitacion(p_hogar_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_codigo text;
  v_nombre text;
begin
  if not public.es_admin_hogar(p_hogar_id) then
    raise exception 'Solo el administrador puede generar códigos de invitación.';
  end if;

  select upper(regexp_replace(coalesce(nombre, ''), '[^A-Za-z0-9]', '', 'g'))
    into v_nombre
    from public.hogar
   where id = p_hogar_id;

  v_codigo := 'INV_'
    || left(coalesce(nullif(v_nombre, ''), 'HOGAR'), 14)
    || '_'
    || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6));

  update public.hogar
     set codigo_invitacion = v_codigo,
         codigo_invitacion_expira_en = now() + interval '7 days',
         updated_at = now()
   where id = p_hogar_id;

  return v_codigo;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_soporte_asignar(p_id uuid, p_agente uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_antes public.solicitud_soporte%rowtype; v_despues public.solicitud_soporte%rowtype;
begin
 if not public.es_admin('SOPORTE_GESTIONAR') then raise exception 'No autorizado.' using errcode='42501'; end if;
 select * into v_antes from public.solicitud_soporte where id=p_id for update;
 if not found then raise exception 'La solicitud no existe.'; end if;
 if v_antes.estado not in('PENDIENTE','ASIGNADA') then raise exception 'La solicitud no se puede asignar en su estado actual.'; end if;
 if not exists(select 1 from public.admin_listar_agentes_soporte() a where a.id=p_agente) then raise exception 'El agente no tiene permisos de soporte.'; end if;
 update public.solicitud_soporte set estado='ASIGNADA',asignado_a=p_agente where id=p_id returning * into v_despues;
 insert into public.auditoria(entidad,entidad_id,accion,perfil_id,antes,despues)
 values('solicitud_soporte',p_id::text,'UPDATE',auth.uid(),
 jsonb_build_object('estado',v_antes.estado,'asignado_a',v_antes.asignado_a),
 jsonb_build_object('operacion','ASIGNAR','estado',v_despues.estado,'asignado_a',v_despues.asignado_a,'asunto',v_despues.asunto));
end;
$function$

CREATE OR REPLACE FUNCTION public.unirse_hogar(p_codigo text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_hogar public.hogar%rowtype;
  v_perfil uuid := auth.uid();
begin
  if v_perfil is null then
    raise exception 'Debes iniciar sesión para unirte a un hogar.';
  end if;

  select *
    into v_hogar
    from public.hogar
   where upper(codigo_invitacion) = upper(trim(p_codigo))
     and (codigo_invitacion_expira_en is null
          or codigo_invitacion_expira_en > now());

  if not found then
    raise exception 'Código de invitación inválido o expirado.';
  end if;

  if exists (
    select 1
      from public.hogar_miembro
     where hogar_id = v_hogar.id
       and perfil_id = v_perfil
       and estado = 'ACTIVO'
  ) then
    raise exception 'Ya perteneces a este hogar.';
  end if;

  insert into public.hogar_miembro (hogar_id, perfil_id, rol, estado, joined_at)
  values (v_hogar.id, v_perfil, 'MIEMBRO', 'ACTIVO', now())
  on conflict (hogar_id, perfil_id) do update
    set rol = 'MIEMBRO',
        estado = 'ACTIVO',
        joined_at = now();

  return v_hogar.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.cambiar_rol_hogar(p_hogar_id uuid, p_perfil_id uuid, p_rol text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_rol text := upper(trim(p_rol));
  v_actual text;
  v_admins integer;
begin
  if not public.es_admin_hogar(p_hogar_id) then
    raise exception 'Solo el administrador puede cambiar roles.';
  end if;

  if v_rol not in ('ADMIN', 'MIEMBRO') then
    raise exception 'Rol no válido.';
  end if;

  select rol into v_actual
    from public.hogar_miembro
   where hogar_id = p_hogar_id
     and perfil_id = p_perfil_id
     and estado = 'ACTIVO';

  if not found then
    raise exception 'El usuario no es miembro de este hogar.';
  end if;

  if v_actual = v_rol then
    return;
  end if;

  if v_actual = 'ADMIN' and v_rol = 'MIEMBRO' then
    select count(*) into v_admins
      from public.hogar_miembro
     where hogar_id = p_hogar_id
       and estado = 'ACTIVO'
       and rol = 'ADMIN';

    if v_admins <= 1 then
      raise exception 'El hogar debe tener al menos un administrador. Transfiere la administración a otro miembro primero.';
    end if;
  end if;

  update public.hogar_miembro
     set rol = v_rol
   where hogar_id = p_hogar_id
     and perfil_id = p_perfil_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.transferir_administracion_hogar(p_hogar_id uuid, p_nuevo_admin uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_yo uuid := auth.uid();
begin
  if not public.es_admin_hogar(p_hogar_id) then
    raise exception 'Solo el administrador puede transferir el hogar.';
  end if;

  if p_nuevo_admin = v_yo then
    raise exception 'Ya eres el administrador de este hogar.';
  end if;

  if not exists (
    select 1
      from public.hogar_miembro
     where hogar_id = p_hogar_id
       and perfil_id = p_nuevo_admin
       and estado = 'ACTIVO'
  ) then
    raise exception 'El usuario no es miembro de este hogar.';
  end if;

  update public.hogar_miembro
     set rol = 'ADMIN'
   where hogar_id = p_hogar_id
     and perfil_id = p_nuevo_admin;

  update public.hogar_miembro
     set rol = 'MIEMBRO'
   where hogar_id = p_hogar_id
     and perfil_id = v_yo;
end;
$function$

CREATE OR REPLACE FUNCTION public.revocar_miembro_hogar(p_hogar_id uuid, p_perfil_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_yo uuid := auth.uid();
begin
  if not public.es_admin_hogar(p_hogar_id) then
    raise exception 'Solo el administrador puede revocar accesos.';
  end if;

  if p_perfil_id = v_yo then
    raise exception 'Para salir del hogar usa la opción Abandonar hogar.';
  end if;

  if not exists (
    select 1
      from public.hogar_miembro
     where hogar_id = p_hogar_id
       and perfil_id = p_perfil_id
       and estado = 'ACTIVO'
  ) then
    raise exception 'El usuario no es miembro de este hogar.';
  end if;

  update public.hogar_miembro
     set estado = 'REMOVIDO'
   where hogar_id = p_hogar_id
     and perfil_id = p_perfil_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_auditar()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_antes jsonb; v_despues jsonb; v_fila jsonb; v_id text; v_accion text := TG_OP;
begin
  if not public.es_admin() then return null; end if;
  if TG_OP <> 'INSERT' then v_antes := to_jsonb(old); end if;
  if TG_OP <> 'DELETE' then v_despues := to_jsonb(new); end if;
  v_fila := coalesce(v_despues, v_antes);
  select string_agg(v_fila ->> k, ':' order by n) into v_id
    from unnest(TG_ARGV) with ordinality as claves(k,n);
  if TG_TABLE_NAME = 'alimento' then
    v_antes := v_antes - 'hogar_id' - 'creado_por';
    v_despues := v_despues - 'hogar_id' - 'creado_por';
  end if;
  if TG_OP = 'UPDATE' then
    if v_antes = v_despues then return null; end if;
    if TG_TABLE_NAME = 'alimento' and v_antes->>'estado' = 'PROPUESTO' then
      if v_despues->>'estado' = 'APROBADO' then v_accion := 'APROBAR';
      elsif v_despues->>'estado' = 'RECHAZADO' then v_accion := 'RECHAZAR'; end if;
    end if;
  end if;
  insert into public.auditoria(entidad,entidad_id,accion,perfil_id,antes,despues,motivo)
    values(TG_TABLE_NAME,v_id,v_accion,auth.uid(),v_antes,v_despues,
      nullif(current_setting('admin.motivo',true),''));
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_soporte_responder(p_id uuid, p_respuesta text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_antes public.solicitud_soporte%rowtype; v_despues public.solicitud_soporte%rowtype;
begin
 if not public.es_admin('SOPORTE_GESTIONAR') then raise exception 'No autorizado.' using errcode='42501'; end if;
 select * into v_antes from public.solicitud_soporte where id=p_id for update;
 if not found then raise exception 'La solicitud no existe.'; end if;
 if p_respuesta is null or char_length(btrim(p_respuesta)) not between 5 and 2000 then raise exception 'La respuesta debe tener entre 5 y 2000 caracteres.'; end if;
 if v_antes.estado='CERRADA' then raise exception 'La solicitud está cerrada.'; end if;
 update public.solicitud_soporte set respuesta=btrim(p_respuesta),respondido_por=auth.uid(),respondido_en=now(),
 asignado_a=coalesce(asignado_a,auth.uid()),estado='RESPONDIDA' where id=p_id returning * into v_despues;
 insert into public.auditoria(entidad,entidad_id,accion,perfil_id,antes,despues)
 values('solicitud_soporte',p_id::text,'UPDATE',auth.uid(),
 jsonb_build_object('estado',v_antes.estado,'asignado_a',v_antes.asignado_a),
 jsonb_build_object('operacion','RESPONDER','estado',v_despues.estado,'asignado_a',v_despues.asignado_a,'asunto',v_despues.asunto));
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_cambiar_estado_cuenta(p_perfil_id uuid, p_estado text, p_motivo text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_estado text; v_email text; v_flag text;
begin
 if not public.es_admin('USUARIOS_SUSPENDER') then raise exception 'No autorizado.' using errcode='42501'; end if;
 if p_estado is null or p_estado not in ('ACTIVA','SUSPENDIDA') then raise exception 'Estado no válido.'; end if;
 if p_motivo is null or char_length(btrim(p_motivo)) not between 5 and 500 then raise exception 'El motivo debe tener entre 5 y 500 caracteres.'; end if;
 if p_perfil_id=auth.uid() then raise exception 'No puedes cambiar el estado de tu propia cuenta.'; end if;
 -- La misma fila de rol que bloquea T01 coordina también la retirada de roles.
 perform pg_advisory_xact_lock(20261024,7);
 perform r.id from public.rol r where r.codigo='ADMIN' for update;
 select p.estado_cuenta,u.email into v_estado,v_email from public.perfil p join auth.users u on u.id=p.id
 where p.id=p_perfil_id for update of p;
 if not found then raise exception 'El usuario no existe.'; end if;
 if v_estado=p_estado then raise exception 'La cuenta ya está en ese estado.'; end if;
 if p_estado='SUSPENDIDA' and exists(select 1 from public.perfil_rol pr join public.rol r on r.id=pr.rol_id where pr.perfil_id=p_perfil_id and r.codigo='ADMIN')
 and not exists(select 1 from public.perfil_rol pr join public.rol r on r.id=pr.rol_id join public.perfil p on p.id=pr.perfil_id
   where r.codigo='ADMIN' and p.estado_cuenta='ACTIVA' and p.id<>p_perfil_id) then
   raise exception 'No se puede suspender al último administrador activo.';
 end if;
 v_flag := coalesce(current_setting('admin.cambio_estado',true),'');
 perform set_config('admin.cambio_estado','1',true);
 update public.perfil set estado_cuenta=p_estado where id=p_perfil_id;
 perform set_config('admin.cambio_estado',v_flag,true);
 insert into public.auditoria(entidad,entidad_id,accion,perfil_id,antes,despues,motivo)
 values('perfil',p_perfil_id::text,case when p_estado='SUSPENDIDA' then 'SUSPENDER' else 'REACTIVAR' end,auth.uid(),
 jsonb_build_object('estado_cuenta',v_estado,'email',v_email),jsonb_build_object('estado_cuenta',p_estado,'email',v_email),btrim(p_motivo));
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_soporte_cerrar(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_antes public.solicitud_soporte%rowtype; v_despues public.solicitud_soporte%rowtype;
