CREATE OR REPLACE FUNCTION public.admin_asignar_rol(p_email text, p_rol_codigo text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;v_rol bigint;v_estado text;
begin
 if not public.es_admin('ROLES_GESTIONAR') then raise exception 'No autorizado.' using errcode='42501'; end if;
 select u.id into v_id from auth.users u where lower(u.email)=lower(btrim(p_email));
 if not found then raise exception 'No existe un usuario registrado con ese correo.'; end if;
 select p.estado_cuenta into v_estado from public.perfil p where p.id=v_id for update;
 if not found or v_estado<>'ACTIVA' then raise exception 'La cuenta del usuario no está activa.'; end if;
 select r.id into v_rol from public.rol r where r.codigo=p_rol_codigo;
 if not found then raise exception 'El rol no existe.'; end if;
 if exists(select 1 from public.perfil_rol pr where pr.perfil_id=v_id and pr.rol_id=v_rol) then raise exception 'El usuario ya tiene ese rol.'; end if;
 insert into public.perfil_rol(perfil_id,rol_id,asignado_por) values(v_id,v_rol,auth.uid());
 return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_quitar_rol(p_perfil_id uuid, p_rol_codigo text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_rol bigint;
begin
 if not public.es_admin('ROLES_GESTIONAR') then raise exception 'No autorizado.' using errcode='42501'; end if;
 if p_perfil_id=auth.uid() then raise exception 'No puedes quitarte tus propios roles.'; end if;
 select r.id into v_rol from public.rol r where r.codigo=p_rol_codigo;
 delete from public.perfil_rol pr where pr.perfil_id=p_perfil_id and pr.rol_id=v_rol;
 if not found then raise exception 'El usuario no tiene ese rol.'; end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.m27_confirmar_compra_item(p_lista_item_id uuid, p_ubicacion text, p_fecha_vencimiento date DEFAULT NULL::date, p_precio_clp integer DEFAULT NULL::integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_item public.lista_compra_item%ROWTYPE;

    v_hogar_id uuid;
    v_estado_lista text;

    v_unidad_base text;
    v_alimento_hogar_id uuid;
    v_estado_alimento text;

    v_cantidad_base numeric;
    v_despensa_item_id uuid;
BEGIN

    -- 1. Usuario autenticado.
    IF (SELECT auth.uid()) IS NULL THEN
        RAISE EXCEPTION
            'Debes iniciar sesión.';
    END IF;

    -- 2. Bloquear el ítem.
    -- Impide duplicarlo ante dos confirmaciones simultáneas.
    SELECT *
    INTO v_item
    FROM public.lista_compra_item
    WHERE id = p_lista_item_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El producto no existe en la lista.';
    END IF;

    -- 3. Obtener el hogar y estado de la lista.
    SELECT hogar_id, estado
    INTO v_hogar_id, v_estado_lista
    FROM public.lista_compra
    WHERE id = v_item.lista_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'La lista de compras no existe.';
    END IF;

    IF NOT public.es_miembro_hogar(v_hogar_id) THEN
        RAISE EXCEPTION
            'No perteneces a este hogar.';
    END IF;

    -- 4. Si ya existe un ingreso vinculado,
    -- no crear otro.
    IF v_item.despensa_item_id IS NOT NULL THEN

        SELECT id
        INTO v_despensa_item_id
        FROM public.despensa_item
        WHERE id = v_item.despensa_item_id
          AND hogar_id = v_hogar_id
          AND alimento_id = v_item.alimento_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION
                'El ingreso vinculado no es válido.';
        END IF;

        RETURN v_despensa_item_id;
    END IF;

    -- 5. Solo convertir compras de listas abiertas.
    IF v_estado_lista <> 'ABIERTA' THEN
        RAISE EXCEPTION
            'La lista de compras no está abierta.';
    END IF;

    -- Se aceptan los COMPRADO antiguos sin vinculación,
    -- además de los PENDIENTE actuales.
    IF v_item.estado NOT IN ('PENDIENTE', 'COMPRADO') THEN
        RAISE EXCEPTION
            'Este producto no se puede ingresar.';
    END IF;

    -- 6. Validar ubicación.
    IF p_ubicacion IS NULL OR
       p_ubicacion NOT IN (
           'DESPENSA',
           'REFRIGERADOR',
           'CONGELADOR'
       )
    THEN
        RAISE EXCEPTION
            'Ubicación no válida.';
    END IF;

    IF p_precio_clp IS NOT NULL
       AND p_precio_clp < 0
    THEN
        RAISE EXCEPTION
            'El precio no puede ser negativo.';
    END IF;

    -- 7. Validar alimento y ámbito del hogar.
    SELECT unidad_base, hogar_id, estado
    INTO
        v_unidad_base,
        v_alimento_hogar_id,
        v_estado_alimento
    FROM public.alimento
    WHERE id = v_item.alimento_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El alimento no existe.';
    END IF;

    IF NOT (
        (
            v_alimento_hogar_id IS NULL
            AND v_estado_alimento = 'APROBADO'
        )
        OR v_alimento_hogar_id = v_hogar_id
    ) THEN
        RAISE EXCEPTION
            'El alimento no está disponible para este hogar.';
    END IF;

    -- 8. Validar compatibilidad de unidades.
    IF (
        v_unidad_base = 'g'
        AND v_item.unidad NOT IN ('g', 'kg')
    ) OR (
        v_unidad_base = 'ml'
        AND v_item.unidad NOT IN ('ml', 'l')
    ) OR (
        v_unidad_base = 'un'
        AND v_item.unidad <> 'un'
    ) THEN
        RAISE EXCEPTION
            'La unidad de compra no coincide con el alimento.';
    END IF;

    -- 9. Convertir a unidad base.
    v_cantidad_base :=
        CASE
            WHEN v_item.unidad IN ('kg', 'l')
                THEN v_item.cantidad * 1000
            ELSE v_item.cantidad
        END;

    IF v_cantidad_base <= 0
       OR v_cantidad_base > 9999999.999
    THEN
        RAISE EXCEPTION
            'La cantidad está fuera del rango permitido.';
    END IF;

    -- Máximo tres decimales en unidad base.
    IF v_cantidad_base <>
       round(v_cantidad_base, 3)
    THEN
        RAISE EXCEPTION
            'La cantidad supera la precisión permitida.';
    END IF;

    -- 10. Registrar nuevo ingreso.
    -- Los triggers de despensa_item realizan
    -- la estimación de fecha y el movimiento INGRESO.
    INSERT INTO public.despensa_item (
        hogar_id,
        alimento_id,
        cantidad_inicial,
        cantidad_restante,
        fecha_vencimiento,
        vencimiento_estimado,
        ubicacion,
        estado,
        precio_clp
    )
    VALUES (
        v_hogar_id,
        v_item.alimento_id,
        v_cantidad_base,
        v_cantidad_base,
        p_fecha_vencimiento,
        false,
        p_ubicacion,
        'DISPONIBLE',
        p_precio_clp
    )
    RETURNING id INTO v_despensa_item_id;

    -- 11. Vincular compra con el ingreso.
    UPDATE public.lista_compra_item
    SET
        estado = 'COMPRADO',
        despensa_item_id = v_despensa_item_id
    WHERE id = v_item.id;

    RETURN v_despensa_item_id;

END;
$function$

CREATE OR REPLACE FUNCTION public.salir_hogar(p_hogar_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_yo uuid := auth.uid();
  v_rol text;
  v_admins integer;
begin
  if not public.es_miembro_hogar(p_hogar_id) then
    raise exception 'No perteneces a este hogar.';
  end if;

  select rol into v_rol
    from public.hogar_miembro
   where hogar_id = p_hogar_id
     and perfil_id = v_yo
     and estado = 'ACTIVO';

  if v_rol = 'ADMIN' then
    select count(*) into v_admins
      from public.hogar_miembro
     where hogar_id = p_hogar_id
       and estado = 'ACTIVO'
       and rol = 'ADMIN';

    if v_admins <= 1 then
      raise exception 'Eres el único administrador. Transfiere la administración antes de abandonar el hogar.';
    end if;
  end if;

  update public.hogar_miembro
     set estado = 'REMOVIDO'
   where hogar_id = p_hogar_id
     and perfil_id = v_yo;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_actualizar_parametro(p_clave text, p_valor text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_tipo text; v_valor text:=btrim(p_valor); v_json jsonb; v_num numeric;
begin
 if not public.es_admin('PARAMETROS_GESTIONAR') then raise exception 'No autorizado.' using errcode='42501'; end if;
 select tipo_dato into v_tipo from public.parametro where clave=p_clave for update;
 if not found then raise exception 'El parámetro no existe.'; end if;
 if v_tipo='ENTERO' and (v_valor is null or v_valor !~ '^-?[0-9]+$') then raise exception 'El valor debe ser un número entero.'; end if;
 if v_tipo='DECIMAL' and (v_valor is null or v_valor !~ '^-?[0-9]+(\.[0-9]+)?$') then raise exception 'El valor debe ser un número decimal.'; end if;
 if v_tipo='BOOLEANO' and (v_valor is null or v_valor not in ('true','false')) then raise exception 'El valor debe ser verdadero o falso.'; end if;
 if v_tipo='TEXTO' and (v_valor is null or char_length(v_valor) not between 1 and 200) then raise exception 'El texto debe tener entre 1 y 200 caracteres.'; end if;
 if v_tipo='JSON' then
   begin v_json:=v_valor::jsonb; if v_json is null then raise exception 'JSON nulo'; end if;
   exception when others then raise exception 'El valor debe ser JSON válido.'; end;
   v_valor:=v_json::text;
 end if;
 if p_clave in ('notif.vencimiento.dias_anticipacion','hogar.max_miembros','hogar.invitacion_vigencia_horas') then
   -- Comparar como numeric evita overflow de int en entradas fuera del rango.
   begin v_num:=v_valor::numeric; exception when others then raise exception 'El valor está fuera del rango permitido.'; end;
   if v_num is null or (p_clave='notif.vencimiento.dias_anticipacion' and v_num not between 0 and 30)
    or (p_clave='hogar.max_miembros' and v_num not between 1 and 20)
    or (p_clave='hogar.invitacion_vigencia_horas' and v_num not between 1 and 720) then raise exception 'El valor está fuera del rango permitido.'; end if;
 end if;
 if p_clave='notif.hora_envio' and (v_valor is null or v_valor !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$') then raise exception 'La hora debe tener formato HH:MM.'; end if;
 if p_clave like '%.canales' then
   if jsonb_typeof(v_json) is distinct from 'array' then raise exception 'Los canales deben ser una lista no vacía de PUSH, EMAIL o IN_APP.'; end if;
   if jsonb_array_length(v_json)=0 or exists(select 1 from jsonb_array_elements(v_json) e where e not in ('"PUSH"'::jsonb,'"EMAIL"'::jsonb,'"IN_APP"'::jsonb))
    or (select count(*) from jsonb_array_elements(v_json))<>(select count(distinct e) from jsonb_array_elements(v_json) e)
    then raise exception 'Los canales deben ser una lista no vacía de PUSH, EMAIL o IN_APP.'; end if;
 end if;
 update public.parametro set valor=v_valor,actualizado_por=auth.uid(),actualizado_en=now() where clave=p_clave;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_reporte_uso(p_desde date, p_hasta date, p_agrupacion text DEFAULT 'MES'::text)
 RETURNS TABLE(periodo date, altas integer, usuarios_activos integer, retencion_pct numeric, productos_registrados integer, alertas_emitidas integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_unit text;
begin
 if not public.es_admin('REPORTES_VER') then raise exception 'No autorizado.' using errcode='42501'; end if;
 if p_desde is null or p_hasta is null or p_desde>p_hasta then raise exception 'El rango de fechas no es válido.'; end if;
 if p_hasta-p_desde+1>366 then raise exception 'El rango no puede superar 366 días.'; end if;
 if p_agrupacion is null or p_agrupacion not in ('MES','SEMANA') then raise exception 'La agrupación no es válida.'; end if;
 v_unit:=case when p_agrupacion='MES' then 'month' else 'week' end;
 return query with periodos as (
 select s::date as periodo,greatest(s::date,p_desde)::timestamp at time zone 'America/Santiago' as inicio,
 least((s+case when p_agrupacion='MES' then interval '1 month' else interval '1 week' end)::date,p_hasta+1)::timestamp at time zone 'America/Santiago' as fin,
 s::timestamp at time zone 'America/Santiago' as inicio_periodo
 from generate_series(date_trunc(v_unit,p_desde::timestamp),date_trunc(v_unit,p_hasta::timestamp),case when p_agrupacion='MES' then interval '1 month' else interval '1 week' end) s
 )
 select p.periodo,
 (select count(*)::int from public.perfil f join auth.users u on u.id=f.id where u.created_at>=p.inicio and u.created_at<p.fin),
 (select count(distinct m.registrado_por)::int from public.movimiento m where m.fecha>=p.inicio and m.fecha<p.fin),
 (select round(100.0*count(*) filter(where exists(select 1 from public.movimiento m where m.registrado_por=f.id and m.fecha>=p.inicio and m.fecha<p.fin))/nullif(count(*),0),1) from public.perfil f join auth.users u on u.id=f.id where u.created_at<p.inicio_periodo),
 (select count(*)::int from public.despensa_item d where d.created_at>=p.inicio and d.created_at<p.fin),
 (select count(*)::int from public.notificacion n where n.estado in ('ENVIADA','LEIDA') and n.programada_para>=p.inicio and n.programada_para<p.fin)
 from periodos p order by p.periodo;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_reporte_desperdicio(p_desde date, p_hasta date, p_agrupacion text DEFAULT 'MES'::text)
 RETURNS TABLE(periodo date, categoria text, descartes integer, hogares integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_unit text;
begin
 if not public.es_admin('REPORTES_VER') then raise exception 'No autorizado.' using errcode='42501'; end if;
 if p_desde is null or p_hasta is null or p_desde>p_hasta then raise exception 'El rango de fechas no es válido.'; end if;
 if p_hasta-p_desde+1>366 then raise exception 'El rango no puede superar 366 días.'; end if;
 if p_agrupacion is null or p_agrupacion not in ('MES','SEMANA') then raise exception 'La agrupación no es válida.'; end if;
 v_unit:=case when p_agrupacion='MES' then 'month' else 'week' end;
 return query select date_trunc(v_unit,m.fecha at time zone 'America/Santiago')::date,raiz.nombre,count(*)::int,count(distinct d.hogar_id)::int
 from public.movimiento m join public.despensa_item d on d.id=m.despensa_item_id
 join public.alimento a on a.id=d.alimento_id join public.categoria c on c.id=a.categoria_id
 join public.categoria raiz on raiz.id=coalesce(c.parent_id,c.id)
 where m.tipo='DESCARTE' and m.fecha>=p_desde::timestamp at time zone 'America/Santiago'
 and m.fecha<(p_hasta+1)::timestamp at time zone 'America/Santiago'
 group by 1,raiz.id,raiz.nombre having count(distinct d.hogar_id)>=3 order by 1,3 desc;
end;
$function$

CREATE OR REPLACE FUNCTION public.registrar_movimiento_despensa(p_despensa_item_id uuid, p_tipo text, p_cantidad numeric, p_tipo_desperdicio_id bigint DEFAULT NULL::bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_yo uuid := auth.uid();
  v_hogar uuid;
  v_restante numeric;
  v_tipo text := upper(trim(p_tipo));
  v_agota boolean;
begin
  if v_yo is null then
    raise exception 'Debes iniciar sesión.';
  end if;

  if v_tipo not in ('CONSUMO', 'DESCARTE') then
    raise exception 'Tipo de movimiento no válido.';
  end if;

  select hogar_id, cantidad_restante
    into v_hogar, v_restante
    from public.despensa_item
   where id = p_despensa_item_id
   for update;

  if not found then
    raise exception 'El ítem no existe.';
  end if;

  if not public.es_miembro_hogar(v_hogar) then
    raise exception 'No tienes acceso a este ítem.';
  end if;

  if p_cantidad is null or p_cantidad <= 0 then
    raise exception 'La cantidad debe ser mayor que cero.';
  end if;

  if p_cantidad > v_restante then
    raise exception 'La cantidad supera lo disponible en el ítem.';
  end if;

  if v_tipo = 'DESCARTE' then
    if p_tipo_desperdicio_id is null then
      raise exception 'Un descarte necesita un motivo.';
    end if;

    if not exists (
      select 1
      from public.tipo_desperdicio td
      where td.id = p_tipo_desperdicio_id
        and td.activo = true
    ) then
      raise exception 'El motivo de descarte no existe.';
    end if;
  else
    if p_tipo_desperdicio_id is not null then
      raise exception 'Un consumo no lleva motivo de descarte.';
    end if;
  end if;

  insert into public.movimiento
    (despensa_item_id, tipo, cantidad, tipo_desperdicio_id, registrado_por, fecha)
  values
    (p_despensa_item_id, v_tipo, p_cantidad, p_tipo_desperdicio_id, v_yo, now());

  v_agota := (v_restante - p_cantidad) <= 0;

  update public.despensa_item
     set cantidad_restante = round(cantidad_restante - p_cantidad, 3),
         estado = case
           when v_agota and v_tipo = 'DESCARTE' then 'DESECHADO'
           when v_agota then 'AGOTADO'
           else estado
         end
   where id = p_despensa_item_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.m08_iniciar_confirmacion_prueba(p_usuario uuid, p_sesion uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_solicitud uuid;
    v_vence timestamptz;
    v_revision jsonb;
BEGIN

    -- 1. Solo puede llamarla el backend.
    IF auth.role() IS DISTINCT FROM 'service_role' THEN
        RAISE EXCEPTION 'Acceso no autorizado';
    END IF;

    -- 2. Exclusivamente nuestra cuenta de prueba.
    IF p_usuario IS DISTINCT FROM
        '9935ceb5-7be9-4d03-becf-3504c8e617c5'::uuid
    THEN
        RAISE EXCEPTION 'Cuenta no autorizada';
    END IF;

    -- 3. Verificar sesión y propietario.
    IF NOT EXISTS (
        SELECT 1
        FROM auth.sessions s
        WHERE s.id = p_sesion
          AND s.user_id = p_usuario
    ) THEN
        RAISE EXCEPTION 'Sesión no válida';
    END IF;

    -- 4. Exigir cuenta ACTIVA.
    -- Bloquear el perfil durante esta operación
    -- para evitar solicitudes simultáneas.
    PERFORM 1
    FROM public.perfil p
    WHERE p.id = p_usuario
      AND p.estado_cuenta = 'ACTIVA'
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Cuenta no activa';
    END IF;

    -- 5. Reutilizar nuestra revisión preliminar.
    v_revision :=
        public.m08_preflight_eliminacion_prueba(
            p_usuario
        );

    IF COALESCE(
        (v_revision ->> 'apto')::boolean,
        false
    ) IS NOT TRUE THEN
        RAISE EXCEPTION
            'La cuenta tiene requisitos pendientes';
    END IF;

    -- 6. Cancelar solicitudes pendientes anteriores.
    UPDATE public.m08_confirmacion_eliminacion
    SET estado = 'CANCELADA'
    WHERE usuario_id = p_usuario
      AND estado = 'PENDIENTE';

    -- 7. Crear solicitud nueva.
    INSERT INTO public.m08_confirmacion_eliminacion (
        usuario_id,
        sesion_id
    )
    VALUES (
        p_usuario,
        p_sesion
    )
    RETURNING id, vence_en
    INTO v_solicitud, v_vence;

    -- 8. Responder sin autorizar la eliminación.
    RETURN jsonb_build_object(
        'exito', true,
        'solicitud_id', v_solicitud,
        'estado', 'PENDIENTE',
        'vence_en', v_vence,
        'eliminacion_autorizada', false
    );

END;
$function$

CREATE OR REPLACE FUNCTION public.m15_guardar_hogar(p_hogar_id uuid DEFAULT NULL::uuid, p_nombre text DEFAULT NULL::text, p_adultos smallint DEFAULT NULL::smallint, p_menores smallint DEFAULT NULL::smallint)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_usuario uuid;
    v_hogar uuid;
    v_nombre text;
BEGIN
    v_usuario := auth.uid();
    v_nombre := trim(coalesce(p_nombre, ''));

    IF v_usuario IS NULL THEN
        RAISE EXCEPTION 'Debes iniciar sesión';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.perfil p
        WHERE p.id = v_usuario
          AND p.estado_cuenta = 'ACTIVA'
    ) THEN
        RAISE EXCEPTION 'Cuenta no habilitada';
    END IF;

    IF length(v_nombre) < 2 OR length(v_nombre) > 80 THEN
        RAISE EXCEPTION
            'El nombre debe tener entre 2 y 80 caracteres';
    END IF;

    IF p_adultos < 0 OR p_menores < 0 THEN
        RAISE EXCEPTION
            'Las cantidades no pueden ser negativas';
    END IF;

    IF p_hogar_id IS NULL THEN

        IF EXISTS (
            SELECT 1
            FROM public.hogar_miembro hm
            WHERE hm.perfil_id = v_usuario
              AND hm.estado = 'ACTIVO'
        ) THEN
            RAISE EXCEPTION
                'Ya perteneces a un hogar. Debes abandonarlo antes de crear otro';
        END IF;

        INSERT INTO public.hogar (
            nombre,
            adultos,
            menores,
            creado_por
        )
        VALUES (
            v_nombre,
            p_adultos,
            p_menores,
            v_usuario
        )
        RETURNING id INTO v_hogar;

        IF EXISTS (
            SELECT 1
            FROM public.hogar_miembro hm
            WHERE hm.hogar_id = v_hogar
              AND hm.perfil_id = v_usuario
        ) THEN

            UPDATE public.hogar_miembro
            SET rol = 'ADMIN',
                estado = 'ACTIVO',
                joined_at = coalesce(joined_at, now())
            WHERE hogar_id = v_hogar
              AND perfil_id = v_usuario;

        ELSE

            INSERT INTO public.hogar_miembro (
                hogar_id,
                perfil_id,
                rol,
                estado,
                joined_at
            )
            VALUES (
                v_hogar,
                v_usuario,
                'ADMIN',
                'ACTIVO',
                now()
            );

        END IF;

        RETURN v_hogar;
    END IF;

    UPDATE public.hogar h
    SET nombre = v_nombre,
        adultos = p_adultos,
        menores = p_menores,
        updated_at = now()
    WHERE h.id = p_hogar_id
      AND EXISTS (
          SELECT 1
          FROM public.hogar_miembro hm
          WHERE hm.hogar_id = h.id
            AND hm.perfil_id = v_usuario
            AND hm.rol = 'ADMIN'
            AND hm.estado = 'ACTIVO'
      )
    RETURNING h.id INTO v_hogar;

    IF v_hogar IS NULL THEN
        RAISE EXCEPTION
            'No tienes permiso para editar este hogar';
    END IF;

    RETURN v_hogar;
END;
$function$

CREATE OR REPLACE FUNCTION public.m16_gestionar_miembro(p_hogar_id uuid, p_accion text, p_perfil_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_usuario uuid;
    v_creador uuid;
    v_rol_actual text;
    v_rol_destino text;
    v_cantidad_admin integer;
BEGIN
    v_usuario := auth.uid();

    IF v_usuario IS NULL THEN
        RAISE EXCEPTION 'Debes iniciar sesión';
    END IF;

    -- Serializa las operaciones M16 del mismo hogar.
    SELECT h.creado_por
    INTO v_creador
    FROM public.hogar h
    WHERE h.id = p_hogar_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Hogar no encontrado';
    END IF;

    -- El solicitante debe pertenecer al hogar.
    SELECT hm.rol
    INTO v_rol_actual
    FROM public.hogar_miembro hm
    WHERE hm.hogar_id = p_hogar_id
      AND hm.perfil_id = v_usuario
      AND hm.estado = 'ACTIVO';

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'No perteneces a este hogar';
    END IF;

    -- Contar administradores activos.
    SELECT count(*)
    INTO v_cantidad_admin
    FROM public.hogar_miembro hm
    WHERE hm.hogar_id = p_hogar_id
      AND hm.estado = 'ACTIVO'
      AND hm.rol = 'ADMIN';

    -- ==========================================
    -- ABANDONAR HOGAR
    -- ==========================================
    IF p_accion = 'ABANDONAR' THEN

        IF v_creador = v_usuario THEN
            RAISE EXCEPTION
                'Debes transferir la administración antes de abandonar';
        END IF;

        IF v_rol_actual = 'ADMIN'
           AND v_cantidad_admin <= 1 THEN
            RAISE EXCEPTION
                'El hogar debe conservar un administrador';
        END IF;

        UPDATE public.hogar_miembro
        SET estado = 'REMOVIDO'
        WHERE hogar_id = p_hogar_id
          AND perfil_id = v_usuario
          AND estado = 'ACTIVO';

        RETURN;
    END IF;

    -- Las demás acciones requieren rol ADMIN.
    IF v_rol_actual <> 'ADMIN' THEN
        RAISE EXCEPTION
            'Solo un administrador puede realizar esta acción';
    END IF;

    IF p_perfil_id IS NULL THEN
        RAISE EXCEPTION
            'Debes seleccionar un integrante';
    END IF;

    IF p_perfil_id = v_usuario THEN
        RAISE EXCEPTION
            'Esta acción no se puede realizar sobre tu propia cuenta';
    END IF;

    SELECT hm.rol
    INTO v_rol_destino
    FROM public.hogar_miembro hm
    WHERE hm.hogar_id = p_hogar_id
      AND hm.perfil_id = p_perfil_id
      AND hm.estado = 'ACTIVO';

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'El integrante no está activo en este hogar';
    END IF;

    -- ==========================================
    -- PROMOVER A ADMIN
    -- ==========================================
    IF p_accion = 'PROMOVER' THEN

        UPDATE public.hogar_miembro
        SET rol = 'ADMIN'
        WHERE hogar_id = p_hogar_id
          AND perfil_id = p_perfil_id
          AND estado = 'ACTIVO';

        RETURN;
    END IF;

    -- ==========================================
    -- DEGRADAR A MIEMBRO
    -- ==========================================
    IF p_accion = 'DEGRADAR' THEN

        IF p_perfil_id = v_creador THEN
            RAISE EXCEPTION
                'Primero debes transferir la administración del creador';
        END IF;

        IF v_rol_destino = 'ADMIN'
           AND v_cantidad_admin <= 1 THEN
            RAISE EXCEPTION
                'No puedes quitar al último administrador';
        END IF;

        UPDATE public.hogar_miembro
        SET rol = 'MIEMBRO'
        WHERE hogar_id = p_hogar_id
          AND perfil_id = p_perfil_id
          AND estado = 'ACTIVO';

        RETURN;
    END IF;

    -- ==========================================
    -- REMOVER INTEGRANTE
    -- ==========================================
    IF p_accion = 'REMOVER' THEN

        IF p_perfil_id = v_creador THEN
            RAISE EXCEPTION
                'No puedes remover al creador sin transferir la administración';
        END IF;

        IF v_rol_destino = 'ADMIN'
           AND v_cantidad_admin <= 1 THEN
            RAISE EXCEPTION
                'No puedes remover al último administrador';
        END IF;

        UPDATE public.hogar_miembro
        SET estado = 'REMOVIDO'
        WHERE hogar_id = p_hogar_id
          AND perfil_id = p_perfil_id
          AND estado = 'ACTIVO';

        RETURN;
    END IF;

    -- ==========================================
    -- TRANSFERIR ADMINISTRACIÓN
    -- ==========================================
    IF p_accion = 'TRANSFERIR' THEN

        -- Primero activar como administrador al destino.
        UPDATE public.hogar_miembro
        SET rol = 'ADMIN'
        WHERE hogar_id = p_hogar_id
          AND perfil_id = p_perfil_id
          AND estado = 'ACTIVO';

        -- El administrador actual pasa a MIEMBRO.
        UPDATE public.hogar_miembro
        SET rol = 'MIEMBRO'
        WHERE hogar_id = p_hogar_id
          AND perfil_id = v_usuario
          AND estado = 'ACTIVO';

        -- Si el solicitante era el creador,
        -- transferir también la titularidad técnica.
        IF v_creador = v_usuario THEN
            UPDATE public.hogar
            SET creado_por = p_perfil_id,
                updated_at = now()
            WHERE id = p_hogar_id;
        END IF;

        RETURN;
    END IF;

    RAISE EXCEPTION 'Acción no válida';
END;
$function$

CREATE OR REPLACE FUNCTION public.m17_generar_invitacion(p_hogar_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_usuario uuid := auth.uid();
    v_codigo text;
    v_expira timestamptz;
    v_intento integer;
BEGIN
    IF v_usuario IS NULL THEN
        RAISE EXCEPTION 'Debes iniciar sesión';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.perfil p
        WHERE p.id = v_usuario
          AND p.estado_cuenta = 'ACTIVA'
    ) THEN
        RAISE EXCEPTION 'Cuenta no habilitada';
    END IF;

    -- Bloquear temporalmente la fila del hogar
    -- para coordinar operaciones concurrentes.
    PERFORM 1
    FROM public.hogar h
    WHERE h.id = p_hogar_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Hogar no encontrado';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.hogar_miembro hm
        WHERE hm.hogar_id = p_hogar_id
          AND hm.perfil_id = v_usuario
          AND hm.rol = 'ADMIN'
          AND hm.estado = 'ACTIVO'
    ) THEN
        RAISE EXCEPTION
            'Solo un administrador puede generar invitaciones';
    END IF;

    -- Código aleatorio de 16 caracteres hexadecimales.
    -- Comprobar que no coincida con otro código vigente.

    FOR v_intento IN 1..10 LOOP
        v_codigo := upper(
            substring(
                replace(
                    pg_catalog.gen_random_uuid()::text,
                    '-',
                    ''
                )
                FROM 1 FOR 16
            )
        );

        EXIT WHEN NOT EXISTS (
            SELECT 1
            FROM public.hogar h
            WHERE h.codigo_invitacion = v_codigo
              AND h.codigo_invitacion_expira_en > now()
        );
    END LOOP;

    IF EXISTS (
        SELECT 1
        FROM public.hogar h
        WHERE h.codigo_invitacion = v_codigo
          AND h.codigo_invitacion_expira_en > now()
    ) THEN
        RAISE EXCEPTION
            'No fue posible generar un código único';
    END IF;

    v_expira := now() + interval '24 hours';

    UPDATE public.hogar
    SET codigo_invitacion = v_codigo,
        codigo_invitacion_expira_en = v_expira,
        updated_at = now()
    WHERE id = p_hogar_id;

    RETURN jsonb_build_object(
        'exito', true,
        'codigo', v_codigo,
        'expira_en', v_expira
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.m17_unirse_hogar(p_codigo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_usuario uuid := auth.uid();
    v_codigo text;
    v_hogar_id uuid;
    v_nombre text;
    v_estado text;
BEGIN
    IF v_usuario IS NULL THEN
        RAISE EXCEPTION 'Debes iniciar sesión';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.perfil p
        WHERE p.id = v_usuario
          AND p.estado_cuenta = 'ACTIVA'
    ) THEN
        RAISE EXCEPTION 'Cuenta no habilitada';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.hogar_miembro hm
        WHERE hm.perfil_id = v_usuario
          AND hm.estado = 'ACTIVO'
    ) THEN
        RAISE EXCEPTION
            'Ya perteneces a un hogar. Debes abandonarlo antes de unirte a otro';
    END IF;

    v_codigo := upper(trim(coalesce(p_codigo, '')));

    IF v_codigo !~ '^[A-F0-9]{16}$' THEN
        RAISE EXCEPTION 'Código de invitación inválido';
    END IF;

    SELECT h.id, h.nombre
    INTO v_hogar_id, v_nombre
    FROM public.hogar h
    WHERE h.codigo_invitacion = v_codigo
      AND h.codigo_invitacion_expira_en > now()
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Código incorrecto o vencido';
    END IF;

    SELECT hm.estado
    INTO v_estado
    FROM public.hogar_miembro hm
    WHERE hm.hogar_id = v_hogar_id
      AND hm.perfil_id = v_usuario;

    IF FOUND THEN
        IF v_estado = 'ACTIVO' THEN
            RAISE EXCEPTION
                'Ya perteneces a este hogar';
        END IF;

        IF v_estado = 'REMOVIDO' THEN
            RAISE EXCEPTION
                'Debes solicitar una nueva autorización para volver';
        END IF;

        IF v_estado = 'INVITADO' THEN
            UPDATE public.hogar_miembro
            SET estado = 'ACTIVO',
                joined_at = now()
            WHERE hogar_id = v_hogar_id
              AND perfil_id = v_usuario;
        ELSE
            RAISE EXCEPTION
                'Estado de membresía no permitido';
        END IF;

    ELSE
        INSERT INTO public.hogar_miembro (
            hogar_id,
            perfil_id,
            rol,
            estado,
            joined_at
        )
        VALUES (
            v_hogar_id,
            v_usuario,
            'MIEMBRO',
            'ACTIVO',
            now()
        );
    END IF;

    RETURN jsonb_build_object(
        'exito', true,
        'hogar_id', v_hogar_id,
        'nombre', v_nombre,
        'rol', 'MIEMBRO'
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.m19_autocalcular_vencimiento()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_dias integer;
    v_dias_alimento integer;
    v_dias_categoria integer;
    v_dias_refrigerador integer;
    v_dias_congelador integer;
    v_temp text;
    v_perecible boolean;
BEGIN
    -- Si existe una fecha manual o personalizada,
    -- respetarla completamente.
    IF NEW.fecha_vencimiento IS NOT NULL THEN
        RETURN NEW;
    END IF;

    -- Buscar las referencias del alimento y su categoría.
    SELECT
        a.vida_util_dias_ref,
        c.vida_util_dias_ref,
        c.vida_util_refrigerado_dias,
        c.vida_util_congelado_dias,
        c.temp_conservacion,
        a.es_perecible
    INTO
        v_dias_alimento,
        v_dias_categoria,
        v_dias_refrigerador,
        v_dias_congelador,
        v_temp,
        v_perecible
    FROM public.alimento a
    JOIN public.categoria c
        ON c.id = a.categoria_id
    WHERE a.id = NEW.alimento_id;

    -- Si el alimento no es perecible, no estimar.
    IF v_perecible IS NOT TRUE THEN
        NEW.vencimiento_estimado := false;
        RETURN NEW;
    END IF;

    -- Elegir una duración referencial según ubicación.
    CASE NEW.ubicacion
        WHEN 'DESPENSA' THEN
            IF v_temp IS NULL OR v_temp = 'AMBIENTE' THEN
                v_dias := COALESCE(
                    v_dias_alimento,
                    v_dias_categoria
                );
            END IF;

        WHEN 'REFRIGERADOR' THEN
            IF v_temp IS NULL OR v_temp = 'REFRIGERADO' THEN
                v_dias := COALESCE(
                    v_dias_alimento,
                    v_dias_refrigerador,
                    v_dias_categoria
                );
            ELSE
                v_dias := v_dias_refrigerador;
            END IF;

        WHEN 'CONGELADOR' THEN
            IF v_temp = 'CONGELADO' THEN
                v_dias := COALESCE(
                    v_dias_alimento,
                    v_dias_congelador,
                    v_dias_categoria
                );
            ELSE
                v_dias := v_dias_congelador;
            END IF;
    END CASE;

    IF v_dias IS NOT NULL AND v_dias > 0 THEN
        NEW.fecha_vencimiento :=
            NEW.fecha_ingreso + v_dias;

        NEW.vencimiento_estimado := true;
    ELSE
        -- No inventar fechas cuando faltan referencias.
        NEW.fecha_vencimiento := NULL;
        NEW.vencimiento_estimado := false;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.m19_registrar_multiples(p_hogar_id uuid, p_items jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_usuario uuid := auth.uid();
    v_item jsonb;

    v_alimento_id bigint;
    v_cantidad numeric;
    v_ubicacion text;
    v_fecha date;
    v_estimado boolean;
    v_precio integer;

    v_total integer := 0;
BEGIN
    -- 1. Validar autenticación.
    IF v_usuario IS NULL THEN
        RAISE EXCEPTION 'Debes iniciar sesión';
    END IF;

    -- 2. Validar hogar y miembro activo.
    IF p_hogar_id IS NULL OR NOT EXISTS (
        SELECT 1
        FROM public.hogar_miembro hm
        JOIN public.perfil p
            ON p.id = hm.perfil_id
        WHERE hm.hogar_id = p_hogar_id
          AND hm.perfil_id = v_usuario
          AND hm.estado = 'ACTIVO'
          AND p.estado_cuenta = 'ACTIVA'
    ) THEN
        RAISE EXCEPTION
            'No tienes permiso para registrar en este hogar';
    END IF;

    -- 3. Verificar formato del conjunto.
    IF p_items IS NULL
       OR jsonb_typeof(p_items) <> 'array'
    THEN
        RAISE EXCEPTION
            'Los alimentos deben enviarse como un arreglo';
    END IF;

    IF jsonb_array_length(p_items) < 1
       OR jsonb_array_length(p_items) > 50
    THEN
        RAISE EXCEPTION
            'Debes registrar entre 1 y 50 alimentos';
    END IF;

    -- 4. Recorrer cada alimento.
    FOR v_item IN
        SELECT value
        FROM jsonb_array_elements(p_items)
    LOOP
        IF jsonb_typeof(v_item) <> 'object' THEN
            RAISE EXCEPTION
                'Cada alimento debe ser un objeto válido';
        END IF;

        v_alimento_id :=
            NULLIF(v_item->>'alimento_id', '')::bigint;

        v_cantidad :=
            NULLIF(v_item->>'cantidad', '')::numeric;

        v_ubicacion := v_item->>'ubicacion';

        v_fecha :=
            NULLIF(
                v_item->>'fecha_vencimiento',
                ''
            )::date;

        v_estimado := COALESCE(
            (v_item->>'vencimiento_estimado')::boolean,
            false
        );

        v_precio :=
            NULLIF(v_item->>'precio_clp', '')::integer;

        -- 5. Validar cantidad.
        IF v_cantidad IS NULL
           OR v_cantidad <= 0
           OR v_cantidad > 9999999.999
           OR v_cantidad <> round(v_cantidad, 3)
        THEN
            RAISE EXCEPTION
                'Cantidad inválida para alimento %',
                v_alimento_id;
        END IF;

        -- 6. Validar ubicación.
        IF v_ubicacion IS NULL
           OR v_ubicacion NOT IN (
               'DESPENSA',
               'REFRIGERADOR',
               'CONGELADOR'
           )
        THEN
            RAISE EXCEPTION
                'Ubicación inválida para alimento %',
                v_alimento_id;
        END IF;

        -- 7. Validar precio opcional.
        IF v_precio IS NOT NULL AND v_precio < 0 THEN
            RAISE EXCEPTION
                'El precio no puede ser negativo';
        END IF;

        -- 8. Validar que el alimento sea accesible.
        IF v_alimento_id IS NULL OR NOT EXISTS (
            SELECT 1
            FROM public.alimento a
            WHERE a.id = v_alimento_id
              AND a.activo = true
              AND (
                  (
                      a.estado = 'APROBADO'
                      AND a.hogar_id IS NULL
                  )
                  OR (
                      a.hogar_id = p_hogar_id
                      AND a.estado IN (
                          'LOCAL',
                          'PROPUESTO',
                          'RECHAZADO'
                      )
                  )
              )
        ) THEN
            RAISE EXCEPTION
                'Alimento no disponible: %',
                v_alimento_id;
        END IF;

        -- 9. Crear una entrada independiente.
        INSERT INTO public.despensa_item (
            id,
            hogar_id,
            alimento_id,
            cantidad_inicial,
            cantidad_restante,
            fecha_ingreso,
            fecha_vencimiento,
            vencimiento_estimado,
            ubicacion,
            estado,
            precio_clp
        )
        VALUES (
            gen_random_uuid(),
            p_hogar_id,
            v_alimento_id,
            v_cantidad,
            v_cantidad,
            (now() AT TIME ZONE 'America/Santiago')::date,
            v_fecha,
            v_estimado,
            v_ubicacion,
            'DISPONIBLE',
            v_precio
        );

        v_total := v_total + 1;
    END LOOP;

    RETURN v_total;
END;
$function$

CREATE OR REPLACE FUNCTION public.editar_item_inventario(p_item_id uuid, p_nueva_cantidad numeric DEFAULT NULL::numeric, p_nueva_ubicacion text DEFAULT NULL::text, p_cambiar_fecha boolean DEFAULT false, p_nueva_fecha date DEFAULT NULL::date, p_cambiar_precio boolean DEFAULT false, p_nuevo_precio integer DEFAULT NULL::integer, p_cambiar_observaciones boolean DEFAULT false, p_nuevas_observaciones text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_usuario uuid := auth.uid();
    v_item public.despensa_item%ROWTYPE;

    v_hoy date := (now() AT TIME ZONE 'America/Santiago')::date;

    v_cantidad numeric;
    v_inicial numeric;
    v_delta numeric;

    v_ubicacion text;
    v_cambio_ubicacion boolean;

    v_fecha date;
    v_estimada boolean;
    v_inicio_congelacion date;
    v_fecha_previa date;

    v_dias_congelado integer;
    v_aviso text;
BEGIN
    -- 1. AUTENTICACIÓN Y CUENTA ACTIVA
    IF v_usuario IS NULL THEN
        RAISE EXCEPTION 'Debes iniciar sesión.';
    END IF;

    IF NOT COALESCE(nfc_seguridad.cuenta_activa(), false) THEN
        RAISE EXCEPTION 'La cuenta no está activa.';
    END IF;

    -- 2. OBTENER Y BLOQUEAR EL ÍTEM
    SELECT *
    INTO v_item
    FROM public.despensa_item
    WHERE id = p_item_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'El alimento no existe.';
    END IF;

    IF NOT public.es_miembro_hogar(v_item.hogar_id) THEN
        RAISE EXCEPTION 'No tienes acceso a este alimento.';
    END IF;

    IF v_item.estado <> 'DISPONIBLE'
       OR v_item.cantidad_restante <= 0 THEN
        RAISE EXCEPTION
            'Solo puedes editar alimentos disponibles.';
    END IF;

    -- 3. AJUSTAR CANTIDAD SIN ALTERAR CONSUMOS
    v_cantidad := COALESCE(
        p_nueva_cantidad,
        v_item.cantidad_restante
    );

    IF v_cantidad <= 0
       OR v_cantidad > 9999999.999
       OR v_cantidad <> round(v_cantidad, 3) THEN
        RAISE EXCEPTION
            'La cantidad debe ser positiva y tener máximo 3 decimales.';
    END IF;

    v_delta := v_cantidad - v_item.cantidad_restante;

    v_inicial := v_item.cantidad_inicial + v_delta;

    IF v_inicial <= 0
       OR v_inicial > 9999999.999 THEN
        RAISE EXCEPTION 'Cantidad inicial corregida no válida.';
    END IF;

    -- 4. DETECTAR CAMBIO DE UBICACIÓN
    v_ubicacion := COALESCE(
        p_nueva_ubicacion,
        v_item.ubicacion
    );

    IF v_ubicacion NOT IN (
        'DESPENSA',
        'REFRIGERADOR',
        'CONGELADOR'
    ) THEN
        RAISE EXCEPTION 'Ubicación no válida.';
    END IF;

    v_cambio_ubicacion :=
        v_ubicacion <> v_item.ubicacion;

    -- 5. CONSERVAR DATOS DE FECHA
    v_fecha := v_item.fecha_vencimiento;
    v_estimada := v_item.vencimiento_estimado;
    v_inicio_congelacion := v_item.fecha_inicio_congelacion;
    v_fecha_previa := v_item.fecha_previa_congelacion;

    -- 6. VALIDAR PRECIO Y OBSERVACIONES
    IF COALESCE(p_cambiar_precio, false)
       AND p_nuevo_precio IS NOT NULL
       AND p_nuevo_precio < 0 THEN
        RAISE EXCEPTION 'El precio no puede ser negativo.';
    END IF;

    IF COALESCE(p_cambiar_observaciones, false)
       AND length(COALESCE(p_nuevas_observaciones, '')) > 500 THEN
        RAISE EXCEPTION
            'Las observaciones admiten máximo 500 caracteres.';
    END IF;

    -- 7. TRASLADO DE UBICACIÓN
    IF v_cambio_ubicacion THEN

        -- DESCONGELACIÓN
        IF v_item.ubicacion = 'CONGELADOR'
           AND v_ubicacion <> 'CONGELADOR' THEN

            -- Nunca conservar una fecha de meses de
            -- congelación como fecha de refrigeración.
            IF NOT COALESCE(p_cambiar_fecha, false)
               OR p_nueva_fecha IS NULL THEN
                RAISE EXCEPTION
                    'Al retirar un alimento del congelador debes indicar una nueva fecha de revisión.';
            END IF;

            v_inicio_congelacion := NULL;

            v_aviso :=
                'Se registró la salida del congelador. Revisa que la fecha indicada sea adecuada al alimento.';

        -- ENTRADA AL CONGELADOR
        ELSIF v_ubicacion = 'CONGELADOR'
              AND v_item.ubicacion <> 'CONGELADOR' THEN

            v_inicio_congelacion := v_hoy;
            v_fecha_previa := v_item.fecha_vencimiento;

            -- Prioridad: alimento específico.
            -- Respaldo: duración congelada de categoría.
            SELECT COALESCE(
                NULLIF(a.vida_util_congelado_dias, 0),
                NULLIF(c.vida_util_congelado_dias, 0)
            )
            INTO v_dias_congelado
            FROM public.alimento a
            LEFT JOIN public.categoria c
                ON c.id = a.categoria_id
            WHERE a.id = v_item.alimento_id;

            IF COALESCE(p_cambiar_fecha, false) THEN
                -- La fecha manual se procesa más abajo.
                NULL;

            ELSIF v_item.vencimiento_estimado = false THEN
                v_aviso :=
                    'Traslado registrado. Se conservó la fecha manual original.';

            ELSIF v_item.fecha_vencimiento IS NULL
               OR v_item.fecha_vencimiento < v_hoy THEN
                v_aviso :=
                    'Traslado registrado, pero no se extendió una fecha estimada ya superada o desconocida.';

            ELSIF v_dias_congelado IS NULL
               OR v_dias_congelado <= 0 THEN
                v_aviso :=
                    'Traslado registrado. Este alimento no tiene duración congelada configurada; revisa su fecha.';

            ELSE
                v_fecha := v_hoy + v_dias_congelado;
                v_estimada := true;

                v_aviso :=
                    'Traslado registrado. Se calculó una referencia de calidad congelada de '
                    || v_dias_congelado || ' días.';
            END IF;

        -- OTROS TRASLADOS
        ELSE
            v_aviso :=
                'Ubicación actualizada. La fecha no se recalculó automáticamente.';
        END IF;
    END IF;

    -- 8. CAMBIO MANUAL DE FECHA: TIENE PRIORIDAD
    IF COALESCE(p_cambiar_fecha, false) THEN
        v_fecha := p_nueva_fecha;
        v_estimada := false;
    END IF;

    -- 9. GUARDAR CAMBIOS
    UPDATE public.despensa_item
    SET
        cantidad_restante = v_cantidad,
        cantidad_inicial = v_inicial,

        ubicacion = v_ubicacion,

        fecha_vencimiento = v_fecha,
        vencimiento_estimado = v_estimada,

        fecha_inicio_congelacion = v_inicio_congelacion,
        fecha_previa_congelacion = v_fecha_previa,

        precio_clp = CASE
            WHEN COALESCE(p_cambiar_precio, false)
                THEN p_nuevo_precio
            ELSE precio_clp
        END,

        observaciones = CASE
            WHEN COALESCE(p_cambiar_observaciones, false)
                THEN NULLIF(trim(p_nuevas_observaciones), '')
            ELSE observaciones
        END

    WHERE id = p_item_id;

    -- 10. REGISTRAR AJUSTE DE CANTIDAD
    IF v_delta <> 0 THEN
        INSERT INTO public.movimiento (
            despensa_item_id,
            tipo,
            cantidad,
            ajuste_delta,
            registrado_por,
            fecha
        )
        VALUES (
            p_item_id,
            'AJUSTE',
            abs(v_delta),
            v_delta,
            v_usuario,
            now()
        );
    END IF;

    -- 11. REGISTRAR TRASLADO EN AUDITORÍA
    IF v_cambio_ubicacion THEN
        INSERT INTO public.auditoria (
            id,
            entidad,
            entidad_id,
            accion,
            perfil_id,
            antes,
            despues,
            fecha,
            motivo
        )
        VALUES (
            gen_random_uuid(),
            'despensa_item',
            p_item_id::text,
            'UPDATE',
            v_usuario,

            jsonb_build_object(
                'ubicacion', v_item.ubicacion,
                'fecha_vencimiento', v_item.fecha_vencimiento,
                'vencimiento_estimado', v_item.vencimiento_estimado
            ),

            jsonb_build_object(
                'ubicacion', v_ubicacion,
                'fecha_vencimiento', v_fecha,
                'vencimiento_estimado', v_estimada,
                'fecha_inicio_congelacion', v_inicio_congelacion,
                'fecha_previa_congelacion', v_fecha_previa
            ),

            now(),
            'TRASLADO_UBICACION'
        );
    END IF;

    -- 12. DEVOLVER RESULTADO A FLUTTER
    RETURN jsonb_build_object(
        'id', p_item_id,
        'cantidad_inicial', v_inicial,
        'cantidad_restante', v_cantidad,
        'ajuste_delta', v_delta,
        'ubicacion_anterior', v_item.ubicacion,
        'ubicacion', v_ubicacion,
        'traslado_registrado', v_cambio_ubicacion,
        'fecha_vencimiento', v_fecha,
        'vencimiento_estimado', v_estimada,
        'fecha_inicio_congelacion', v_inicio_congelacion,
        'fecha_previa_congelacion', v_fecha_previa,
        'aviso', v_aviso
    );
END;
$function$

CREATE OR REPLACE FUNCTION nfc_m28_privado.procesar_alertas_programadas()
 RETURNS TABLE(canceladas integer, generadas integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN

    -- Primero limpiar avisos pendientes obsoletos.
    canceladas :=
        nfc_m28_privado.cancelar_alertas_pendientes(
            NULL::uuid
        );

    -- Después generar los avisos que correspondan.
    generadas :=
        nfc_m28_privado.generar_alertas_programadas(
            NULL::uuid
        );

    RETURN NEXT;

END;
$function$

CREATE OR REPLACE FUNCTION public.m28_sincronizar_alertas()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_usuario uuid;
    v_canceladas integer;
    v_generadas integer;
BEGIN

    v_usuario := (SELECT auth.uid());

    IF v_usuario IS NULL THEN
        RAISE EXCEPTION 'Debes iniciar sesión';
    END IF;

    IF NOT COALESCE(
        nfc_seguridad.cuenta_activa(),
        false
    ) THEN
        RAISE EXCEPTION 'La cuenta no está activa';
    END IF;

    -- Limpiar exclusivamente los avisos propios.
    v_canceladas :=
        nfc_m28_privado.cancelar_alertas_pendientes(
            v_usuario
        );

    -- Generar exclusivamente los avisos propios.
    v_generadas :=
        public.m28_generar_alertas_internas();

    RETURN jsonb_build_object(
        'canceladas', v_canceladas,
        'generadas', v_generadas
    );

END;
$function$
